        die(f"检查点 {path} 已损坏（顶层不是对象）—— 修好或删掉它；拒绝覆盖")
    issues = raw.get("issues")
    if not isinstance(issues, dict):
        die(f"检查点 {path} 已损坏（没有 `issues` 对象）—— 修好或删掉它；拒绝覆盖")
    for key, entry in issues.items():
