// JoinSlug 把多段文本各自转成 slug 后用 "/" 串起来，空白段（含空串）被跳过。
func JoinSlug(parts ...string) string {
	slugs := make([]string, 0, len(parts))
	for _, part := range parts {
		if slug := Slug(part); slug != "" {
			slugs = append(slugs, slug)
		}
	}
	return strings.Join(slugs, "/")
}

